// The agent's trust boundary (docs/SPEC.md, "Trust boundary"): it can open PRs, comment and label.
// It cannot push to main, publish, merge, change CI, hand-edit generated reports, approve visual
// baselines or loosen its own autonomy settings.

/** Paths only a human may change. Generated files are regenerated by their scripts instead. */
export const PROTECTED_PATHS = [
  { pattern: /(^|\/)\.github\/workflows\//, why: 'CI configuration is maintained by humans' },
  { pattern: /(^|\/)api\/[^/]+\.json$/, why: 'API reports are generated: run `pnpm api:report`' },
  { pattern: /(^|\/)public\/r\/[^/]+\.json$/, why: 'the registry is generated: run `pnpm registry:build`' },
  { pattern: /(^|\/)public\/(llms(-full)?\.txt|install\.md)$/, why: 'agent docs are generated: run `pnpm docs:build`' },
  { pattern: /(^|\/)packages\/mcp\/data\/components\.json$/, why: 'the MCP catalogue is generated: run `pnpm docs:build`' },
  { pattern: /(^|\/)__screenshots__\//, why: 'only a human can approve a visual baseline; propose it in the PR instead' },
  { pattern: /(^|\/)\.changeset\/config\.json$/, why: 'release configuration is maintained by humans' },
  { pattern: /(^|\/)agent\/config\.yaml$/, why: 'autonomy thresholds are set by maintainers' },
  { pattern: /(^|\/)eslint\.config\.js$/, why: 'lint rules (including tokens-only) are maintained by humans' },
];

export function protectedReason(path) {
  return PROTECTED_PATHS.find(({ pattern }) => pattern.test(path))?.why ?? null;
}

/** Read the hook payload from stdin. */
export async function readInput() {
  let raw = '';
  for await (const chunk of process.stdin) raw += chunk;
  return JSON.parse(raw || '{}');
}

/** Exit code 2 blocks the tool call; stderr is shown to the agent as the reason. */
export function block(reason) {
  process.stderr.write(`Blocked by the machine-ui agent policy: ${reason}\n`);
  process.exit(2);
}
